const CRM_PAUSED_TODO_TYPES=new Set(["收款待办","备货待办","邀请函审核","邀请函审批","邀请函审核待办","邀请函审批待办","公海跟进","公海跟进待办","客户跟进","客户跟进待办"]);function crmTodoEnabled(value){return!CRM_PAUSED_TODO_TYPES.has(typeof value==="string"?value:value?.type)}const CRM_ORDER_ONLY_FLOW=!crmTodoEnabled("收款待办")&&!crmTodoEnabled("备货待办");
